//-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
//	NAME:					HE_SNMP_Get
//	CREATOR:				Helgevold - Jan Magne Dybvik
// REQUIREMENTS: NX CPU
//
// DESCRTIPTION: 	Leser en Portstatus via SNMP Get-Request
//-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
//  VERSION LOG:
//	 VERSION			DATE				SIGN							DESCRIPTION
//	 1.0					2024-05-15		Jan Magne Dybvik		Initial release
//	 1.1					2024-06-11		Jan Magne Dybvik		Lagt til tellere for feil og suksess
//  1.1.1				2024-09-11		Jan Magne Dybvik		Teller for flere forsøk før resultatet nullstilles, Enumeration for definering av tilstand
//  1.1.2				2024-09-13		Jan Magne Dybvik		Se etter Error i ConfigureRequest steget
//	 1.1.3				2025-04-30		Ruben Byman				Økt Wrk_OID til 48
//	 1.1.4				2025-05-20		Jan Magne Dybvik		Timeout av Config og Response steg for å unngå heng
//	 2.0.0				2026-04-22		Ruben Byman				Rework to match updated structure
//
//================================================================================================================================

(*************************************************************************
 *	ASSIGNS TOKEN
 *************************************************************************)
 
IF TokenID = -1 THEN
	FOR TokenID:=0 TO DINT_TO_UINT(UPPER_BOUND(Ext_Telegram.Token_Static, 1)) DO
		IF NOT Ext_Telegram.Token_Static[TokenID] THEN
			Ext_Telegram.Token_Static[TokenID]:=TRUE;
			EXIT;
		END_IF;
	END_FOR;
END_IF;

(*************************************************************************
 *	TIMEOUT (If too long time in state)
 *************************************************************************)
 
IF Ext_Telegram.Token_Active = TokenID THEN
	Wrk_TimeInState:=ADD_TIME(In1:=Wrk_TimeInState, In2:=GetMyTaskInterval());
	IF Wrk_State <> Wrk_SampleState THEN
	Wrk_TimeInState:=TIME#0ms;
	Wrk_SampleState:= Wrk_State;
	END_IF;
ELSE
	Wrk_TimeInState:=TIME#0ms;
	Wrk_State:= 0;
END_IF;

IF Wrk_TimeInState > Ext_Telegram.Timeout THEN
	Wrk_ErrorCode := 16#8000000; // Timeout error code
	Inc(Ext_Telegram.Token_Active);
	Wrk_TimeInState:=TIME#0ms;
END_IF;

(*************************************************************************
 *	CASE FOR REQUEST & DATA SEND
 *************************************************************************)
 
CASE Wrk_State OF
	
	0: // Wait for turn
		IF Ext_Telegram.Token_Active = TokenID THEN
			
			//Setting common parameters
			Ext_Telegram.RemotePort:= Cfg_RemotePort;
			Ext_Telegram.RemoteIP:= Cfg_RemoteIP;
			Ext_Telegram.Community:= Cfg_Community;
			IF Cfg_SNMP_ver1 THEN
				Ext_Telegram.SNMP_Ver:=0;
			ELSE
				Ext_Telegram.SNMP_Ver := 1;
			END_IF;
			Wrk_Done := FALSE;
			Wrk_Busy := TRUE;
			Wrk_State := 10;
		END_IF;
		
	10: // Configure SNMP request
		IF NOT Ext_Telegram.Busy THEN
			Ext_Telegram.OID := Cfg_OID;
			Ext_Telegram.Execute := TRUE;
			Wrk_State := 11;
			
		END_IF;
	
	11: // Wait for completion
		IF Ext_Telegram.Done THEN
			Val_ResponseValue := Ext_Telegram.ResponseValue;
			Val_ResponseString := Ext_Telegram.ResponseString;
			Val_ResponseValue_64 := Ext_Telegram.ResponseValue_64;
			Wrk_CommStatus := Ext_Telegram.Comm_OK;
			Wrk_State := 1000;
			Ext_Telegram.Execute := FALSE;
			
		ELSIF Ext_Telegram.Error THEN
			Val_ResponseValue := 0;
			Val_ResponseString := '';
			Val_ResponseValue_64 := 0;
			Wrk_CommStatus := Ext_Telegram.Comm_OK;
			Wrk_State := 1001;
			Ext_Telegram.Execute := FALSE;
			
		END_IF;

	1000: //Completed OK
		Inc(Ext_Telegram.Token_Active);
		Wrk_State := 0;
		Wrk_SNMP_Error :=FALSE;
		Ext_Telegram.Execute := FALSE;
		Wrk_Done := TRUE;
		Wrk_Busy := FALSE;
		Wrk_Successes := Wrk_Successes + 1;
	
	1001: //General error
		Inc(Ext_Telegram.Token_Active);
		Wrk_State := 0;
		Wrk_SNMP_Error :=TRUE;
		Wrk_Errors := Wrk_Errors + 1;
		Wrk_ErrorCode := Ext_Telegram.ErrorCode;
		Ext_Telegram.Execute := FALSE;
		Wrk_Busy := FALSE;

END_CASE;

(*************************************************************************
 *	PERFORMING LOGIC
 *************************************************************************)
 
//Communication OK
TOF_CommOK(In:=Wrk_CommStatus, PT:=T#5s);

(*************************************************************************
 *	UPDATING OUTPUTS
 *************************************************************************)
 
 Sts_CommOK := NOT TOF_CommOK.Q;
 Sts_Done := Wrk_Done;
 Sts_Error := Wrk_SNMP_Error;
 Sts_Busy := Wrk_Busy;
